For any of the four norms, any $x$ supported in a finite initial $D$, any $y\in F_D$, and $t>0$, one has $$\label{eq:pair-inequality}
 \frac{\|x+ty\|_K+\|x-ty\|_K}{2}
 \ge \sqrt{1-\theta^2}\,\|x\|_K
       +\frac{t\theta}{2}\|y\|_K
       \qquad(0\le\theta\le\tfrac12).$$

If $x,y\in X$, $P_Ax=x$ and $P_Ay=0$ for a finite head $A$, then, for every $c>0$, $$\max\{\|x+y\|,\|x-y\|\}
 \ge\frac{\|x\|+c\|y\|/2}{\sqrt{1+4c^2}}.
 \label{eq:linear-clipping-family}$$ In particular the left side is at least $\sqrt{\|x\|^2+\|y\|^2/16}$.

For a finite head projection $P$ on $X$, $$\label{eq:linear-trimming-242}
 \|y\|^2\le242\bigl(\|x+y\|^2+\|x-y\|^2-2\|x\|^2\bigr)
 \qquad(Px=x,\ Py=0).$$

Let $$C=\frac12\sum_{\epsilon\in\{+,-\}}
       (\|h^\epsilon\|_H^2+\|\lambda^\epsilon\|_L^2),
 \qquad E=C-\|x\|_{\mathrm q}^2.$$

For a finite ancestral head $A$, $P_Ax=x$, and $P_Ay=0$, $$\label{qp:symmetric-144}
 \|x\|_{\mathrm q}^2+\frac{\|y\|_{\mathrm q}^2}{144}
 \le\frac{\|x+y\|_{\mathrm q}^2+\|x-y\|_{\mathrm q}^2}{2}.$$

For every nonzero $x\in X_{\mathrm q}$ and $0<\delta\le1$ there is a finite ancestral head $A$, depending only on $x,\delta$, such that for every $u\in X_{\mathrm q}$, $$\|x+u\|_{\mathrm q},\ \|x-u\|_{\mathrm q}
       \le(1+\delta)\|x\|_{\mathrm q}
 \quad\Longrightarrow\quad
 \|Q_Au\|_{\mathrm q}\le72\sqrt\delta\,\|x\|_{\mathrm q}.$$

On $\ell_2(\mathcal T_n)$ the formula $$\|x\|_{S,n}=\inf\{M_n(m(a)):Pa=x\}$$ defines a complete reflexive norm, with $$\label{sm:s:norm-comparisons}
 \frac{\|x\|_2}{n+1}\le\|x\|_{S,n}
 \le\sqrt{n+1}\,\|x\|_2.$$

For every $x\in X_S$ with $\|x\|_S=1$, every $t>0$ and every $\varepsilon>0$ there is a closed finite-codimensional subspace $F\subset X_S$ such that $$\inf_{\substack{y\in F\\\|y\|_S=1}}
 \max\{\|x+ty\|_S,\|x-ty\|_S\}
 \ge\sqrt{1+t^2/64}-\varepsilon.$$

