For any of the four norms, any $x$ supported in a finite initial $D$, any $y\in F_D$, and $t>0$, one has $$\label{eq:pair-inequality}
 \frac{\|x+ty\|_K+\|x-ty\|_K}{2}
 \ge \sqrt{1-\theta^2}\,\|x\|_K
       +\frac{t\theta}{2}\|y\|_K
       \qquad(0\le\theta\le\tfrac12).$$

If $x,y\in X$, $P_Ax=x$ and $P_Ay=0$ for a finite head $A$, then, for every $c>0$, $$\max\{\|x+y\|,\|x-y\|\}
 \ge\frac{\|x\|+c\|y\|/2}{\sqrt{1+4c^2}}.
 \label{eq:linear-clipping-family}$$ In particular the left side is at least $\sqrt{\|x\|^2+\|y\|^2/16}$.

Let $C=6(\sqrt2+1)$. In one component, if $P_Ax=x$, $P_Ay=0$, and $L_n(x\pm y)\le1$, then $$\label{eq:linear-positive-unit}
 L_n(y)\le C\sqrt{1-L_n(x)}.$$ For arbitrary $x,y$ satisfying $P_Ax=x$ and $P_Ay=0$, writing $\beta=\max\{L_n(x+y),L_n(x-y)\}$ and $r=L_n(x)$, one has $$\label{eq:linear-positive-scaled}
 L_n(y)^2\le C^2\beta(\beta-r)\le C^2(\beta^2-r^2).$$ Consequently, for a finite head projection $P$ on $X$, $$\label{eq:linear-positive-outer}
 \|y\|^2\le C^2\bigl(\|x+y\|^2+\|x-y\|^2-2\|x\|^2\bigr)
 \quad(Px=x,\ Py=0).$$

Suppose $0\le\varepsilon\le1$, $P_Ax=x$, $P_Ay=0$, $L_n(x\pm y)\le1$, and $L_n(x)\ge1-\varepsilon$. Then $$\label{eq:linear-bottom-up-explicit}
 L_n(y)\le3\sqrt{2\varepsilon}+8\varepsilon.$$ Moreover the following uniform implication holds on $X$: for any sequence of finite head projections $P_j$ and vectors satisfying $$P_jx_j=x_j,\quad P_jy_j=0,\quad
 \|x_j\pm y_j\|\le1,\quad\|x_j\|\longrightarrow1,$$ one has $\|y_j\|\longrightarrow0$.

For a finite head projection $P$ on $X$, $$\label{eq:linear-trimming-242}
 \|y\|^2\le242\bigl(\|x+y\|^2+\|x-y\|^2-2\|x\|^2\bigr)
 \qquad(Px=x,\ Py=0).$$ The same assertion, with $L_n$ in place of $\|\cdot\|$, holds in each component.

Let $A\subseteq A'$ be finite ancestor-closed subsets of the disjoint union of the $T_n$, and put $E=A'\setminus A$. If $P_Ax=x$ and $P_{A'}y=y$, then $$\label{eq:linear-fresh-layer-400}
 \|P_Ey\|^2\le400\left(
       \frac{\|x+y\|^2+\|x-y\|^2}{2}-\|x\|^2\right).$$ There is no condition on $P_Ay$.

Let $x_0,\ldots,x_m$ be an $X$-valued dyadic martingale. Let $P_0$ be a fixed finite initial set, and, for $1\le i\le m$, let $P_i$ be a finite initial set measurable with respect to $\mathcal F_{i-1}$. Suppose, on every history, that $$P_{i-1}\subseteq P_i\quad(1\le i\le m),\qquad
 \operatorname{supp}x_i\subseteq P_i\quad(0\le i\le m),\qquad \|x_m\|\le C.$$ Then, for $\Delta_i=P_i\setminus P_{i-1}$, $$\label{eq:linear-energy-495}
 \sum_{i=1}^m\mathbb E\|R_{\Delta_i}x_i\|^2\le495C^2.$$

The spaces $Z_n$ and $X_{\mathrm q}$ are Banach and reflexive, and finite node support is dense in $X_{\mathrm q}$. For $z\in H_n$, $$\label{qp:comparison}
 \frac{\|z\|_2}{\sqrt{n+2}}\le |z|_n\le\|z\|_2,
 \qquad |z_t|\le\sqrt2\,|z|_n.$$ In particular $1/\sqrt2\le |p_t|_n,|e_t|_n\le1$, and $|e_o|_n=1/\sqrt2$. For $f\in\ell_2(T_n)$ the dual norm is $$\label{qp:dual}
 |f|_{n,*}=
 \left(\|f\|_2^2+
     \sup_{t\in T_n}\left|\sum_{s\preceq t}f_s\right|^2\right)^{1/2}.$$

Let $$C=\frac12\sum_{\epsilon\in\{+,-\}}
       (\|h^\epsilon\|_H^2+\|\lambda^\epsilon\|_L^2),
 \qquad E=C-\|x\|_{\mathrm q}^2.$$ Then $$\begin{aligned}
 \|Q\bar h\|_H^2+\|\widetilde h\|_H^2+
       \sum_n(M_n^2-q_n^2)&\le E,\label{qp:energy-mean}\\
 \tfrac12(\|Qh^+\|_H^2+\|Qh^-\|_H^2)+
       \sum_n d_n^2&\le E.\label{qp:energy-endpoints}
\end{aligned}$$

For a finite ancestral head $A$, $P_Ax=x$, and $P_Ay=0$, $$\label{qp:symmetric-144}
 \|x\|_{\mathrm q}^2+\frac{\|y\|_{\mathrm q}^2}{144}
 \le\frac{\|x+y\|_{\mathrm q}^2+\|x-y\|_{\mathrm q}^2}{2}.$$

For every nonzero $x\in X_{\mathrm q}$ and $0<\delta\le1$ there is a finite ancestral head $A$, depending only on $x,\delta$, such that for every $u\in X_{\mathrm q}$, $$\|x+u\|_{\mathrm q},\ \|x-u\|_{\mathrm q}
       \le(1+\delta)\|x\|_{\mathrm q}
 \quad\Longrightarrow\quad
 \|Q_Au\|_{\mathrm q}\le72\sqrt\delta\,\|x\|_{\mathrm q}.$$

For every $x\in X_{\mathrm q}$ with $\|x\|_{\mathrm q}=1$ and $0<e\le1/16$, there is a closed finite-codimensional subspace $Y\subset X_{\mathrm q}$ such that $$\label{qp:rec:complete-bound}
 y\in Y,\quad
 \|x+y\|_{\mathrm q},\|x-y\|_{\mathrm q}\le1+e
 \quad\Longrightarrow\quad
 \|y\|_{\mathrm q}\le17(2e)^{1/6}.$$ In particular, for every $t>0$ there is an $e_t>0$, independent of the unit center $x$, for which some closed finite-codimensional $Y$ satisfies $$\inf_{u\in S_Y}
 \max\{\|x+tu\|_{\mathrm q},\|x-tu\|_{\mathrm q}\}\ge1+e_t.$$ Here $S_Y=\{u\in Y:\|u\|_{\mathrm q}=1\}$. Thus the maximum asymptotic midpoint modulus is positive at every positive radius.

On $\ell_2(\mathcal T_n)$ the formula $$\|x\|_{S,n}=\inf\{M_n(m(a)):Pa=x\}$$ defines a complete reflexive norm, with $$\label{sm:s:norm-comparisons}
 \frac{\|x\|_2}{n+1}\le\|x\|_{S,n}
 \le\sqrt{n+1}\,\|x\|_2.$$ Consequently $$X_S=\Bigl(\bigoplus_{n\ge1}(\ell_2(\mathcal T_n),\|\cdot\|_{S,n})
       \Bigr)_{\ell_2}$$ is a reflexive Banach space. Write $\|\cdot\|_S$ for its norm. Equivalently, $\|x\|_S$ is the infimum of $M(m(a))$ over all forest representations of $x$. Finite-support vectors are dense.

Let $C$ be a finite ancestral subset of $\mathcal T$. If $p\in X_S$ is supported in $C$ and $y\in X_S$ satisfies $y|_C=0$, then $$\label{sm:s:tail}
 \max\{\|p+y\|_S,\|p-y\|_S\}^2
 \ge\|p\|_S^2+\frac{\|y\|_S^2}{64}.$$ The conclusion includes $C=\varnothing$, $p=0$ and $y=0$.

For every $x\in X_S$ with $\|x\|_S=1$, every $t>0$ and every $\varepsilon>0$ there is a closed finite-codimensional subspace $F\subset X_S$ such that $$\inf_{\substack{y\in F\\\|y\|_S=1}}
 \max\{\|x+ty\|_S,\|x-ty\|_S\}
 \ge\sqrt{1+t^2/64}-\varepsilon.$$ In particular, define the maximum form of the asymptotic midpoint modulus by $$\delta^{\max}_{X_S}(t)=
 \inf_{\|x\|_S=1}\sup_{\substack{F\subset X_S\text{ closed}\\\dim(X_S/F)<\infty}}
 \inf_{\substack{y\in F\\\|y\|_S\ge1}}
 \bigl(\max_{\pm}\|x\pm ty\|_S-1\bigr).$$ Then $\delta^{\max}_{X_S}(t)\ge\sqrt{1+t^2/64}-1$.

Let $Y_{\mathrm I,h}$ be the completion of the arrays supported on $T_h$ in the norm <a href="#sm:i:norm" data-reference-type="eqref" data-reference="sm:i:norm">[sm:i:norm]</a>. Then $$\frac{\|g\|_2}{\sqrt{h+1}}
 \leq\|g\|_{Y_{\mathrm I,h}}
 \leq\sqrt{h+1}\,\|g\|_2,
 \qquad g\in c_{00}(T_h),
 \label{sm:i:hilbert}$$ and $$Y_{\mathrm I}=\left(\bigoplus_{h\geq1}Y_{\mathrm I,h}\right)_{\ell_2}.$$ Both $Y_{\mathrm I}$ and $X_{\mathrm I}:=Y_{\mathrm I}^*$ are reflexive.
